import { MeshBasicNodeMaterial, PlaneGeometry, Mesh, Object3D } from 'three/webgpu';

export default function createNode(config, ctx) {
  // --- Geometry ---
  const geometry = new PlaneGeometry(2, 1.25); // aspect ratio 512/320 = 1.6, but we use unit size; adjust later if needed

  // --- Texture ---
  const texture = ctx.textureLoader.load(config.assets?.imageUrl || '/prism-assets/chrome/brushed-metal.map.png');
  // Assuming atlas region is exactly the texture's full size; otherwise UV offset/scale could be applied.
  // If atlas is larger, we'd need atlas dimensions from config. Here we assume no offset needed.

  // --- Material ---
  const material = new MeshBasicNodeMaterial({
    map: texture,
    color: 0xffffff,
    roughness: 0.6, // subtle grain hint
    metalness: 0.3,
  });

  // --- Mesh ---
  const mesh = new Mesh(geometry, material);
  mesh.castShadow = false;
  mesh.receiveShadow = false;

  // --- Position / Rotation / Scale from config ---
  const sp = config.scenePosition || {};
  mesh.position.set(sp.x ?? 3.2, sp.y ?? -0.3, sp.z ?? 0);
  mesh.rotation.set(sp.rotX ?? 0, sp.rotY ?? 0, sp.rotZ ?? 0);
  mesh.scale.set(sp.sX ?? 1, sp.sY ?? 1, sp.sZ ?? 1);

  // --- User data ---
  mesh.userData.handlers = {};
  mesh.userData.cleanup = () => {
    texture.dispose();
    material.dispose();
    geometry.dispose();
  };

  // --- Apply cinematic primitives (none) ---
  if (config.cinematicPrimitives) {
    for (const prim of config.cinematicPrimitives) {
      ctx.primitives[prim.name](mesh, prim.params);
    }
  }

  return mesh;
}
